@click.command(no_args_is_help=False)
@click.option("--pairs", multiple=True, type=(str, str))
def cmd1(pairs):
    print("pairs:", pairs)

ctx = cmd1.make_context("c", [], default_map={"pairs": "a b c d"})
cmd1.invoke(ctx)

# tuple already in default_map
ctx = cmd1.make_context("c", [], default_map={"pairs": (("a", "b"), ("c", "d"))})
cmd1.invoke(ctx)

# nargs=-1
@click.command(no_args_is_help=False)
@click.option("--items", nargs=-1, type=int)
def cmd2(items):
    print("items:", items)

ctx = cmd2.make_context("c", [], default_map={"items": "1 2 3"})
cmd2.invoke(ctx)

# Path type uses pathsep splitting, like envvar
@click.command(no_args_is_help=False)
@click.option("--paths", multiple=True, type=click.Path())
def cmd3(paths):
    print("paths:", paths)

ctx = cmd3.make_context("c", [], default_map={"paths": f"./a{os.path.pathsep}./b"})
cmd3.invoke(ctx)

# Path type: compare env var behavior
os.environ["P3"] = "x"  # not used

# flag option with string default should NOT be split
@click.command(no_args_is_help=False)
@click.option("--name", default=None)
def cmd4(name):
    print("name:", repr(name))

ctx = cmd4.make_context("c", [], default_map={"name": "hello world"})
cmd4.invoke(ctx)

