import os
import click

# multiple=True, nargs=2, tuple type
@click.command(no_args_is_help=False)
@click.option("--pairs", multiple=True, nargs=2, type=(str, str), envvar="PAIRS")
def cmd1(pairs):
    print("pairs:", pairs)

os.environ["PAIRS"] = "a b c d"
cmd1.invoke(cmd1.make_context("c", []))
del os.environ["PAIRS"]
cmd1.invoke(cmd1.make_context("c", [], default_map={"pairs": "a b c d"}))
