# multiple=True, nargs=1
@click.command(no_args_is_help=False)
@click.option("--nums", multiple=True, type=int, envvar="NUMS")
def cmd2(nums):
    print("nums:", nums)

os.environ["NUMS"] = "1 2 3"
cmd2.invoke(cmd2.make_context("c", []))
del os.environ["NUMS"]
cmd2.invoke(cmd2.make_context("c", [], default_map={"nums": "1 2 3"}))
cmd2.invoke(cmd2.make_context("c", [], default_map={"nums": [1, 2, 3]}))

# nargs=-1 argument
@click.command(no_args_is_help=False)
@click.argument("items", nargs=-1, type=int)
def cmd3(items):
    print("items:", items)

cmd3.invoke(cmd3.make_context("c", [], default_map={"items": "1 2 3"}))
cmd3.invoke(cmd3.make_context("c", ["4", "5"], default_map={"items": "1 2 3"}))

